export type ListJobsParams = {
search?: string;
companyId?: string;
workMode?: ListJobsWorkMode;
jobType?: ListJobsJobType;
status?: ListJobsStatus;
eligibleBatch?: number;
minCgpaLte?: number;
deadlineBefore?: string;
/**
 * Phase 2.0. Only rows whose normalised location is (true) or is not (false) in India. Rows the normaliser could not place (isIndia null) never match either value — select the `unknown` bucket in `locations` to see them.
 */
isIndia?: boolean;
/**
 * Phase 2.0. Only rows whose location carries a remote marker.
 */
isRemote?: boolean;
/**
 * Phase 2.0 location buckets, OR-ed together; omit for no location filtering. A metro name (NCR, MMR, Bengaluru, Hyderabad, Pune, Chennai, Kolkata, or any other locationMetro value) matches that metro exactly. `remote` = remote roles not scoped to another country. `other_india` = India rows naming a city outside the seven featured metros. `india_unspecified` = India rows that state no city at all (bare 'India') — not "elsewhere", just unstated. `unknown` = rows the normaliser could not place — kept reviewable rather than hidden. Filtering is server-side; the list is bounded, so nothing is filtered in the browser.
 */
locations?: string[];
/**
 * Phase 2.1. Only rows the relevance classifier put on the internship, new_grad or early_career track (true) or ruled out (false). Rows not yet classified count as false. Omit for no relevance filtering — the pre-2.1 behaviour exactly.
 */
isFresherEligible?: boolean;
/**
 * Phase 2.1 tracks, OR-ed together. Unclassified rows never match.
 */
relevanceTrack?: ListJobsRelevanceTrackItem[];
/**
 * Phase 2.1. Only rows scoring at least this (0–100).
 * @minimum 0
 * @maximum 100
 */
minRelevanceScore?: number;
/**
 * Phase 3.2. By default a signed-in caller's dismissed jobs are hidden; set true to see them again. Ignored for an anonymous caller, who has no dismissals — the list is then exactly the pre-3.2 one.
 */
showDismissed?: boolean;
/**
 * Phase 7. Work modes OR-ed together; omit for no work-mode filtering. Distinct from the single-valued `workMode` above, which is unchanged. Previously applied in the browser over the fetched window, which is why it could disagree with the result count.
 */
workModes?: ListJobsWorkModesItem[];
/**
 * Phase 7. Graduation years OR-ed together. A posting that names NO eligible batch matches any of them — most postings name none, and hiding those would empty the list.
 */
batches?: number[];
/**
 * Phase 7. Branches OR-ed together. Same "names none matches anything" rule as `batches`.
 */
branches?: string[];
/**
 * Phase 7. Required skills OR-ed together. Unlike `batches` and `branches` there is NO empty-allowance: a posting that lists no skills matches nothing here.
 */
skills?: string[];
/**
 * Phase 7. Exact match on the provider a posting came from.
 */
sourcePlatform?: string;
/**
 * Phase 7. Hide rows the signed-in caller already has an application for, in any pipeline stage. Ignored for an anonymous caller, who has no applications.
 */
hideApplied?: boolean;
/**
 * `newest` (default, the pre-2.1 order — posted date desc), `relevance` (Phase 2.1 — relevanceScore desc, unclassified last, newest first among equal scores), or the Phase 7 additions: `deadline` (soonest first, no deadline last), `salary` (the best of salaryMax / salaryMin / stipend, highest first) and `company` (company name, A–Z). The last three were browser-side sorts over the fetched window before Phase 7 and so only ever ordered part of the result set.
 */
sort?: ListJobsSort;
/**
 * @minimum 1
 */
page?: number;
/**
 * Rows per page. Phase 7 raised the server-side cap from 100 to 200; a larger value is clamped rather than rejected.
 * @minimum 1
 * @maximum 200
 */
limit?: number;
};

